// RateLimiter interface: add
/** Gives back one previously recorded hit (e.g. a reservation that turned out not to be a failure). */
refund(key: string): void;

// MemoryRateLimiter: add
refund(key: string): void {
  const now = this.clock.now().getTime();
  const w = this.windows.get(key);
  if (w && w.resetAt > now && w.count > 0) w.count -= 1;
}

private async resolveCode(studentId: string, code: string): Promise<string> {
  const key = `join-fail:${studentId}`;
  const gate = this.failedAttempts.hit(key); // reserve synchronously, before any await
  if (!gate.allowed) {
    throw new AppError('RATE_LIMITED', 'Too many invalid codes. Wait and try again.', {
      retryAfterSeconds: gate.retryAfterSeconds,
    });
  }
  const found = await new JoinCodeRepository(this.db).findLatestByCode(code);
  const now = this.clock.now();
  if (!found || found.revokedReason === 'regenerated') throw invalidCode(); // keeps the reservation
  this.failedAttempts.refund(key); // only invalid guesses count (D16)
  if (found.revokedReason === 'expired' || found.expiresAt <= now) {
    throw new AppError('JOIN_CODE_EXPIRED', 'This code has expired. Ask your teacher for a new one.');
  }
  if (!found.joiningOpen) {
    throw new AppError('JOINING_CLOSED', 'The teacher has closed joining for this class.');
  }
  return found.classroomId;
}

// Before inserting an enrollment (and in preview), after resolving the classroom:
const isDemo = (sub: string) => sub.startsWith('demo:') || sub.startsWith('seed:');
if (isDemo(teacher.google_sub) !== isDemo(student.google_sub)) {
  throw new AppError('JOIN_CODE_INVALID', 'This code is not valid.');
}
